def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return max(0.0, min(budget, DAILY_SALARY * 0.75))
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    yesterday_bids = []
    dangerous_bids = []
    rich_alive = 0
    for agent_id, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_alive += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            yesterday_bids.append(bid)
            if opp.get('budget', 0) > 0:
                dangerous_bids.append(bid)

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    highest_danger = max(dangerous_bids) if dangerous_bids else highest_prev

    tight_supply = supply <= 18
    medium_supply = supply <= 21
    urgent = hp <= 2 or no_water_days >= 1
    pressured = hp <= 4

    target = 0.0

    if urgent:
        if highest_danger > 0:
            target = highest_danger + 2.0
        else:
            target = DAILY_SALARY * 0.9
    elif tight_supply:
        if highest_danger >= DAILY_SALARY * 1.5:
            target = DAILY_SALARY * 0.42
        elif highest_danger >= DAILY_SALARY * 0.9:
            target = highest_danger + 1.5
        elif highest_danger > 0:
            target = max(DAILY_SALARY * 0.58, highest_danger + 1.0)
        else:
            target = DAILY_SALARY * 0.52
    elif medium_supply:
        if pressured and highest_danger > 0:
            target = max(DAILY_SALARY * 0.6, highest_danger + 1.0)
        elif highest_danger >= DAILY_SALARY * 1.4:
            target = DAILY_SALARY * 0.3
        else:
            target = DAILY_SALARY * 0.4
    else:
        if pressured:
            target = DAILY_SALARY * 0.5
        else:
            target = DAILY_SALARY * 0.22

    if rich_alive >= 2 and not urgent and highest_danger >= DAILY_SALARY * 1.4:
        target = min(target, DAILY_SALARY * 0.35)

    if budget < DAILY_SALARY * 0.6 and not urgent:
        target = min(target, DAILY_SALARY * 0.28)

    if day >= 8 and hp >= 6 and not urgent:
        target = min(target, DAILY_SALARY * 0.3)

    bid = max(0.0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
