    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no active opponents, bid low to save budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            # Only consider bids that are significant, to filter out dead/inactive players' zero bids
            if prev['bid'] > 0:
                yesterday_bids.append(prev['bid'])

    # If no significant previous bids (e.g., Day 1 or all active opponents had no trace)
    if not yesterday_bids:
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9) # Critical, bid high
        return min(my_status['budget'], DAILY_SALARY * 0.55) # Moderate bid

    highest_prev_bid = max(yesterday_bids)

    # Scenario 1: Opponents are bidding very high (e.g., above 90% of my DAILY_SALARY)
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        if my_status['hp'] > 4: # Relatively healthy
            # Try to save budget but stay competitive. Bid competitively but not overpay.
            # Cap at 110% of my daily salary to prevent excessive spending.
            return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid * 0.95), DAILY_SALARY * 1.1)
        else: # Critical or near critical HP
            # Bid very aggressively to win water. Ensure a strong minimum bid.
            # Cap at 120% of my daily salary.
            return max(DAILY_SALARY * 0.9, min(my_status['budget'], highest_prev_bid + 5, DAILY_SALARY * 1.2))
    # Scenario 2: Opponents are bidding moderately
    else: # highest_prev_bid < DAILY_SALARY * 0.9
        # Bid slightly above the highest previous bid to secure water.
        # Cap at 100% of my daily salary.
        return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 3), DAILY_SALARY * 1.0)

